// Run with: node test.js   (do not edit this file)
const assert = require('node:assert/strict')
const { execFileSync } = require('node:child_process')
const { toCents, fmt } = require('./src/money')
const { tax, discount, total } = require('./src/pricing')
const { paginate } = require('./src/paginate')
const { createCart } = require('./src/cart')
const { addBusinessDays } = require('./src/dates')
const { byPriority } = require('./src/sort')

if (process.argv[2] === '--dates') {
  assert.equal(addBusinessDays('2026-03-06', 1), '2026-03-09')
  assert.equal(addBusinessDays('2026-03-05', 2), '2026-03-09')
  assert.equal(addBusinessDays('2026-03-06', 5), '2026-03-13')
  process.exit(0)
}

const tests = {
  'toCents 19.99': () => assert.equal(toCents(19.99), 1999),
  'fmt negative': () => assert.equal(fmt(-550), '-$5.50'),
  'tax rounds half up': () => assert.equal(tax(1000, 8.25), 83),
  'tax 999': () => assert.equal(tax(999, 8.25), 82),
  'discount': () => assert.equal(discount(1999, 10), 200),
  'total with tax and discount': () => assert.equal(total([{ cents: 1999, qty: 3 }], { taxPct: 8.25, discountPct: 10 }), 5842),
  'paginate first page': () => assert.deepEqual(paginate([1, 2, 3, 4, 5], 1, 2).items, [1, 2]),
  'paginate last page': () => assert.deepEqual(paginate([1, 2, 3, 4, 5], 3, 2).items, [5]),
  'paginate totalPages': () => assert.equal(paginate([1, 2, 3, 4, 5], 1, 2).totalPages, 3),
  'carts do not share items': () => {
    const a = createCart()
    const b = createCart()
    a.add('x')
    assert.deepEqual(b.items, [])
  },
  'cart leaves the given array alone': () => {
    const src = ['a']
    createCart(src).add('b')
    assert.deepEqual(src, ['a'])
  },
  'dates in UTC, Los Angeles and Kiritimati': () => {
    for (const TZ of ['UTC', 'America/Los_Angeles', 'Pacific/Kiritimati'])
      execFileSync(process.execPath, [__filename, '--dates'], { env: { ...process.env, TZ }, stdio: 'pipe' })
  },
  'byPriority order': () => {
    const t = [{ id: 'a', priority: 1 }, { id: 'b', priority: 3 }, { id: 'c', priority: 3 }, { id: 'd', priority: 2 }]
    assert.deepEqual(byPriority(t).map((x) => x.id), ['b', 'c', 'd', 'a'])
  },
  'byPriority leaves input alone': () => {
    const t = [{ id: 'a', priority: 1 }, { id: 'b', priority: 3 }]
    byPriority(t)
    assert.equal(t[0].id, 'a')
  },
}

let failed = 0
for (const [name, fn] of Object.entries(tests)) {
  try {
    fn()
    console.log('ok   ' + name)
  } catch (e) {
    failed++
    console.log('FAIL ' + name + ' -> ' + String(e.message).split('\n')[0].slice(0, 140))
  }
}
console.log(failed ? `${failed} failed` : 'all passed')
process.exit(failed ? 1 : 0)
